import {createLiveKeylock} from './keylock-shadow-live.js';
const $=s=>document.querySelector(s),hash=async bytes=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');
const files=['keylock-shadow-live.js','pcm-resample.js','keylock-disposal-151-harness.js','vendor/signalsmith-stretch/SignalsmithStretch-open-play-replace.mjs'];
async function identities(){return Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f,{cache:'no-store'})).arrayBuffer())])));}
$('#dispose-run').onclick=async()=>{const r={checkpoint:151,scope:'Actual AudioContext/eighteen-channel WASM live adapter disposal/reference counters only; silent physical graph. Not app Stop workflow, GC, process memory, continuity or full parity acceptance.',errors:[]};let context,adapter;
try{$('#dispose-run').disabled=true;r.sourceBefore=await identities();context=new AudioContext({sampleRate:44100});await context.resume();const buffers=Array.from({length:5},()=>context.createBuffer(2,44100,44100));for(const b of buffers)for(let c=0;c<2;c++)for(let i=0;i<b.length;i++)b.getChannelData(c)[i]=.06*Math.sin(2*Math.PI*(c?550:330)*i/44100);adapter=await createLiveKeylock(context,{buffers,rate:1.1,keylock:true,semitones:3,resamplePitch:true,reserveStems:true});const silent=context.createGain();silent.gain.value=0;silent.connect(context.destination);for(const output of adapter.outputs)output.connect(silent);await adapter.start({position:0,when:context.currentTime+.2});await new Promise(resolve=>setTimeout(resolve,350));r.before=adapter.snapshot();r.beforeRetainedReferences=adapter.sources.filter(s=>s.buffer).length;r.actualWorklet=await adapter.active.nodes[0].resourceSnapshot();if(!r.before.state.playing||r.beforeRetainedReferences!==5)throw Error('Owner not actually playing with five buffers');r.disposal=await adapter.dispose();r.after=adapter.snapshot();r.afterRetainedReferences=adapter.sources.filter(s=>s.buffer).length;r.passed=r.after.disposed&&r.after.groups.length===0&&r.after.retainedPCMBytes===0&&r.after.decodedBytes===0&&r.after.sourceGeometry.length===0&&r.afterRetainedReferences===0;
}catch(error){r.errors.push({message:error.message,stack:error.stack});r.passed=false;}finally{await adapter?.dispose();await context?.close();r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);r.passed=!!r.passed&&r.sourceStable&&!r.errors.length;$('#dispose-results').textContent=JSON.stringify(r,null,2);$('#dispose-status').textContent=r.passed?'Live disposal counters passed; context closed':'Failed: '+r.errors.map(e=>e.message).join('; ');}};
